<!DOCTYPE html>
<html>
<head>
<title>Mini Spreadsheet</title>
<style>
table {
  border-collapse: collapse;
}

td {
  width: 50px;
  height: 30px;
  text-align: center;
  font-size: 16px;
  border: 1px solid black;
}

input[type="text"] {
  width: 46px;
  height: 26px;
  box-sizing: border-box;
}

button {
  padding: 8px 16px;
  background-color: #4CAF50;
  color: white;
  border: none;
  cursor: pointer;
}
</style>
</head>
<body>

<table>
  <script>
    const sheet = {};
    for (let i = 1; i <= 10; i++) {
      for (let j = 1; j <= 10; j++) {
        const cellId = `cell-${j}-${i}`;
        sheet[cellId] = {
          raw: '',
          computed: ''
        };

        const inputElement = document.getElementById(cellId);
        inputElement.value = sheet[cellId].computed;
        inputElement.addEventListener('click', () => {
          inputElement.type = 'text';
          inputElement.select();
        });
        inputElement.addEventListener('blur', () => {
          sheet[cellId].raw = inputElement.value;
          evaluateCell(cellId);
          inputElement.type = 'number'; // or 'text' based on the input type
        });

        inputElement.addEventListener('keydown', (event) => {
            if (event.key === 'Enter') {
                sheet[cellId].raw = inputElement.value;
                evaluateCell(cellId);
                inputElement.blur(); // simulate blur event
            }
        });
      }
    }

    function evaluateCell(cellId) {
      const [colStr, rowStr] = cellId.slice(5).split('-');
      const col = parseInt(colStr) - 1;
      const row = parseInt(rowStr) - 1;
      let rawValue = sheet[cellId].raw;

      if (rawValue.startsWith('=')) {
        try {
          // Basic evaluation with limited support for some functions and operators
          const expression = rawValue.slice(1); // Remove the leading '='
          let result;
          try{
            result = eval(expression);
          } catch (e){
              sheet[cellId].computed = '#ERR';
              return;
          }

          if (!isNaN(result)) {
            sheet[cellId].computed = result.toString();
          } else {
            sheet[cellId].computed = '#ERR';
          }


        } catch (error) {
          sheet[cellId].computed = '#CYCLE';
        }
      } else {
        const value = parseFloat(rawValue);
        if (!isNaN(value)) {
          sheet[cellId].computed = value.toString();
        } else {
          sheet[cellId].computed = rawValue;
        }
      }

      // Recalculate dependent cells
      for (let i = 1; i <= 10; i++) {
        for (let j = 1; j <= 10; j++) {
          const depCellId = `cell-${j}-${i}`;
          if (sheet[depCellId] && sheet[depCellId].computed !== '#CYCLE' && sheet[depCellId].raw === '' && sheet[depCellId].computed !== '') { // Only recalculate if it wasn't already computed and is not a cycle cell
            evaluateCell(depCellId);
          }

        }
      }
    }


    // Initialize the spreadsheet with some initial values
    sheet["cell-1-1"] = { raw: "10", computed: "10" };
    sheet["cell-1-2"] = { raw: "=A1*2", computed: "=A1*2" };
    sheet["cell-1-3"] = { raw: "5", computed: "5" };
    sheet["cell-2-1"] = { raw: "20", computed: "20" };
    sheet["cell-2-2"] = { raw: "=A1*4", computed: "=A1*4" };
    sheet["cell-2-3"] = { raw: "8", computed: "8" };

    // Evaluate initial values when the page loads
    for (let i = 1; i <= 10; i++) {
      for (let j = 1; j <= 10; j++) {
        const cellId = `cell-${j}-${i}`;
        if (sheet[cellId].raw !== '') {
          evaluateCell(cellId);
        }
      }
    }


  </script>
</table>

<button id="export">Export CSV</button>
<textarea id="csv"></textarea>

</body>
</html>
